style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("web.roblox.com") {
/* -----------------------
     Fixed background layer
     ----------------------- */
  /* clear any root/body backgrounds first */
  html, body, #rbx-body, #wrap, #container-main, .container-main,
  .site, .main, .page, .site-content, .content, .container-lg {
    background: transparent !important;
    background-image: none !important;
  }

  /* place the image in a fixed pseudo-element */
  html::before {
    content: "" !important;
    position: fixed !important;
    inset: 0 !important;
    pointer-events: none !important;
    background-image: url("https://i.imgur.com/hjJNn1S.jpeg") !important;
    background-position: center center !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    z-index: 0 !important;
    opacity: 1 !important;
    filter: none !important;
  }

  /* ensure top-level page children appear above the background */
  html > body > *, html > body, body > * ,
  #wrap, #container-main, .site, .main, .page, .content, .site-content, .container-lg {
    position: relative !important;
    z-index: 1 !important;
  }

  /* remove any Roblox pseudo-element backgrounds that may cover the page */
  body::before, body::after, html::after,
  #rbx-body::before, #rbx-body::after, .site::before, .site::after {
    background: transparent !important;
    background-image: none !important;
    content: none !important;
  }

  /* specifically override the dark-theme on body */
  body.rbx-body.dark-theme,
  body.rbx-body.dark-theme::before,
  body.rbx-body.dark-theme::after {
    background: transparent !important;
    background-image: none !important;
  }

  /* make canvas / game view wrappers transparent (if present) */
  canvas, .game-canvas, #game-viewport, .viewport, .game-embed {
    background: transparent !important;
    background-image: none !important;
  }

  /* -----------------------
     Recreate readable panels
     ----------------------- */
  .content, .container-main, .page-content, .rbx-body,
  .profile-content, .section-content, .rbx-card, .games-page,
  .game-home-page, .game-main-content {
    background: rgba(16,18,24,0.62) !important;
    backdrop-filter: blur(8px) saturate(120%) !important;
    -webkit-backdrop-filter: blur(8px) saturate(120%) !important;
    border-radius: 12px !important;
    border: 1px solid rgba(255,255,255,0.06) !important;
    z-index: 2 !important;
  }

  .site-header, .rbx-header, header, .navbar, .rbx-navbar {
    background: rgba(16,18,24,0.88) !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    border-bottom: 1px solid rgba(255,255,255,0.08) !important;
    z-index: 3 !important;
  }

  /* text / controls */
  h1,h2,h3,h4,h5,h6,p,span,label,.rbx-text { color: #e9eef6 !important; }
  a, .rbx-link { color: #00d0ff !important; }
  a:hover, .rbx-link:hover { filter: brightness(1.15) !important; }

  .btn-primary, .rbx-btn-primary {
    background: #00d0ff !important;
    border: none !important;
    color: #001018 !important;
  }
  .btn-primary:hover, .rbx-btn-primary:hover { filter: brightness(1.1) !important; }

  input, textarea, select, .rbx-input, .form-control {
    background: rgba(255,255,255,0.06) !important;
    color: #e9eef6 !important;
    border: 1px solid rgba(255,255,255,0.08) !important;
  }
  input::placeholder, textarea::placeholder { color: rgba(233,238,246,0.65) !important; }

  /* footer */
  footer, .site-footer {
    background: rgba(16,18,24,0.7) !important;
    color: #b9c0cc !important;
    border-top: 1px solid rgba(255,255,255,0.08) !important;
    z-index: 2 !important;
  }

  /* scrollbar cosmetic */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: rgba(0,0,0,0.35); }
  ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.25); border-radius: 10px; }
}
